// =============================================================================
func (q *Queries) GetPendingDispositions(ctx context.Context) ([]DispositionRequest, error) {
	rows, err := q.db.Query(ctx, getPendingDispositions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DispositionRequest
	for rows.Next() {
		var i DispositionRequest
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.DocumentVersionID,
			&i.RequestedBy,
			&i.Reason,
			&i.Status,
			&i.ApprovedBy,
			&i.ApprovedAt,
			&i.ExecutedAt,
			&i.ExecutedBy,
			&i.ExecutionEvidence,
			&i.ErrorMessage,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

